from openpyxl import load_workbook

wb = load_workbook('gdp.xlsx')
task = wb['Task']

print("Task Sheet - Row 9 and 10 (checking year headers):")
for row in [9, 10]:
    for col in range(1, 13):
        val = task.cell(row=row, column=col).value
        if val is not None:
            print(f"  Row {row}, Col {col} ({chr(64+col) if col <= 26 else chr(64+col)}): {val}")

print("\nTask Sheet - Row 34 (Step 2 years):")
for col in range(1, 13):
    val = task.cell(row=34, column=col).value
    if val is not None:
        print(f"  Col {col}: {val}")
EOF
